//! Parity and regression tests for the qwen3 SNAC TTS family.
//!
//! Pinned fixtures reside in `testdata/tts_qwen3/`, generated by
//! `tools/gen_qwen3_fixtures.py` against mlx-audio 0.5.7 commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3). The
//! generator runs the true reference module (its network codec patched
//! for a tiny seeded instance), so the traces carry `parse_output`,
//! `decode_audio_from_codes`, and `encode_audio_to_codes` outputs from
//! the reference code (the qwen3 reference splits the flat codes inline
//! in its decode), greedy generate loops driven by
//! `mlx_audio.lm.generate.generate_step`, and the sampler math on fixed
//! logits.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{
    codes_to_layers, decode_audio_from_codes, encode_audio_to_codes, GenerateParams, Model,
    StopReason, END_OF_HUMAN, END_OF_SPEECH, END_OF_TEXT, START_OF_HUMAN, START_OF_SPEECH,
};
use crate::codec::snac::Snac;
use crate::tts::sampling;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_qwen3")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Filtered log-prob entries use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// Measured maximum difference against the fixture traces when the
/// gates were frozen; assertions use these values, not re-measured ones.
/// Waveform parity measured 1.1e-9 (conv accumulation order); the
/// sampler stages are bit-exact except the log-softmax reduction at
/// 9.6e-7, so the gates sit two-plus orders above the measurements.
const WAVEFORM_TOLERANCE: f32 = 1e-7;
const SAMPLING_TOLERANCE: f32 = 2e-6;

fn decode_snac() -> Snac {
    Snac::open(&testdata("decode")).expect("tiny codec loads")
}

#[test]
fn parse_output_matches_the_reference_cases() {
    let traces = read_json(&testdata("decode/traces.json"));
    for case in traces["parse_cases"].as_array().expect("cases") {
        let input = i32_vec(&case["input_ids"]);
        let want = i32_vec(&case["codes"]);
        let got = Model::parse_output(&input);
        assert_eq!(got, want, "parse case {}", case["name"]);
    }
}

#[test]
fn codes_to_layers_splits_flat_groups_into_snac_levels() {
    let traces = read_json(&testdata("decode/traces.json"));
    let flat = i32_vec(&traces["flat_codes"]);
    let got = codes_to_layers(&flat).expect("splits");
    let want: Vec<Vec<i32>> = traces["layers"]
        .as_array()
        .expect("layers")
        .iter()
        .map(i32_vec)
        .collect();
    assert_eq!(got, want);
    // Round trip: flat groups reassemble from the levels.
    let mut rebuilt = Vec::with_capacity(flat.len());
    for group in 0..want[0].len() {
        rebuilt.push(want[0][group]);
        rebuilt.push(want[1][group * 2] + 4096);
        rebuilt.push(want[2][group * 4] + 2 * 4096);
        rebuilt.push(want[2][group * 4 + 1] + 3 * 4096);
        rebuilt.push(want[1][group * 2 + 1] + 4 * 4096);
        rebuilt.push(want[2][group * 4 + 2] + 5 * 4096);
        rebuilt.push(want[2][group * 4 + 3] + 6 * 4096);
    }
    assert_eq!(rebuilt, flat);
}

#[test]
fn codes_to_layers_refuses_an_incomplete_group() {
    // The reference group count (len + 1) / 7 would index out of bounds
    // on a remainder-of-6 tail; the port refuses by name instead.
    let error = codes_to_layers(&[0; 6]).unwrap_err();
    assert!(error.to_string().contains("one code short"), "{error}");
    assert_eq!(codes_to_layers(&[0; 7]).unwrap()[0].len(), 1);
}

#[test]
fn decode_audio_from_codes_matches_the_tiny_codec() {
    let traces = read_json(&testdata("decode/traces.json"));
    let flat = i32_vec(&traces["flat_codes"]);
    let snac = decode_snac();
    let got = decode_audio_from_codes(&snac, &flat, &mut || 0.0).expect("decodes");
    let want = f32_vec(&traces["waveform"]);
    assert_eq!(got.len(), want.len());
    let diff = max_abs_diff(&got, &want);
    assert!(diff <= WAVEFORM_TOLERANCE, "decode waveform diff {diff}");
}

#[test]
fn decode_audio_from_codes_refuses_empty_input() {
    let snac = decode_snac();
    let error = decode_audio_from_codes(&snac, &[], &mut || 0.0).unwrap_err();
    assert!(error.to_string().contains("empty code list"), "{error}");
}

#[test]
fn encode_audio_to_codes_matches_the_tiny_codec() {
    let traces = read_json(&testdata("decode/traces.json"));
    let wave = f32_vec(&traces["encode_wave"]);
    let snac = decode_snac();
    let got = encode_audio_to_codes(&snac, &wave).expect("encodes");
    assert_eq!(got, i32_vec(&traces["encode_flat_codes"]));
}

#[test]
fn prepare_input_ids_and_zeroprompt_match_the_reference_layout() {
    assert_eq!(
        Model::prepare_input_ids(&[7, 8, 9], None),
        vec![START_OF_HUMAN, 7, 8, 9, END_OF_TEXT, END_OF_HUMAN]
    );
    let traces = read_json(&testdata("decode/traces.json"));
    let wave = f32_vec(&traces["encode_wave"]);
    let transcript = i32_vec(&traces["zeroprompt_transcript_ids"]);
    let snac = decode_snac();
    let zeroprompt = Model::prepare_zeroprompt(&snac, &wave, &transcript).expect("zeroprompt");
    assert_eq!(zeroprompt, i32_vec(&traces["zeroprompt"]));
    // prepare_input_ids with a zeroprompt prefixes it verbatim.
    let text = Model::prepare_input_ids(&[42], Some(&zeroprompt));
    assert_eq!(&text[..zeroprompt.len()], &zeroprompt[..]);
    assert_eq!(
        &text[zeroprompt.len()..],
        &[START_OF_HUMAN, 42, END_OF_TEXT, END_OF_HUMAN]
    );
}

fn generate_model() -> Model {
    Model::open(&testdata("generate")).expect("family model loads")
}

fn scenario_params(max_tokens: usize, penalty: f32) -> GenerateParams {
    GenerateParams {
        temperature: 0.0,
        top_p: 0.8,
        top_k: -1,
        logit_bias: Vec::new(),
        repetition_penalty: penalty,
        repetition_context_size: 20,
        max_tokens,
    }
}

fn run_generate_scenario(scenario: &Value) {
    let traces = read_json(&testdata("generate/traces.json"));
    let prompt = i32_vec(&traces["prompt"]);
    let mut model = generate_model();
    let params = scenario_params(
        scenario["max_tokens"].as_u64().expect("max_tokens") as usize,
        scenario["repetition_penalty"].as_f64().expect("penalty") as f32,
    );
    // These scenarios carry deliberately non-audio generated ids, so the
    // loop runs through the tokens-only path and the codes are compared
    // without a decode; the waveform composition is pinned by the
    // eos-first case below.
    let (tokens, stopped_by) = model
        .generate_tokens_from_prompt(&prompt, &params, 0)
        .unwrap_or_else(|error| panic!("scenario {} generate failed: {error}", scenario["name"]));
    if tokens != i32_vec(&scenario["generated"]) {
        panic!(
            "scenario {} tokens differ: got {:?}",
            scenario["name"],
            &tokens[..tokens.len().min(24)]
        );
    }
    let mut input_ids = prompt.clone();
    input_ids.extend_from_slice(&tokens);
    assert_eq!(
        Model::parse_output(&input_ids),
        i32_vec(&scenario["codes"]),
        "parsed codes for scenario {}",
        scenario["name"]
    );
    let want_stopped = scenario["stopped_by"].as_str().expect("stopped_by");
    match (want_stopped, stopped_by) {
        ("end_of_speech", StopReason::EndOfSpeech) | ("max_tokens", StopReason::MaxTokens) => {}
        _ => panic!("scenario {} stopped by {:?}", scenario["name"], stopped_by),
    }
}

#[test]
fn greedy_generation_decodes_the_waveform_when_eos_fires_first() {
    // A second seeded backbone whose first greedy draw is the
    // end-of-speech token: the loop appends EOS, stops, and the parsed
    // codes are exactly the prompt's slot-valid groups, so the segment
    // waveform decodes cleanly.
    let traces = read_json(&testdata("generate_eos/traces.json"));
    let prompt = i32_vec(&traces["prompt"]);
    let mut model = Model::open(&testdata("generate_eos")).expect("eos model loads");
    let params = scenario_params(
        traces["max_tokens"].as_u64().expect("max_tokens") as usize,
        traces["repetition_penalty"].as_f64().expect("penalty") as f32,
    );
    let got = match model.generate_from_prompt(&decode_snac(), &prompt, &params, 0) {
        Ok(got) => got,
        Err(error) => panic!("eos-first generate failed: {error}"),
    };
    assert_eq!(got.tokens, i32_vec(&traces["generated"]));
    assert_eq!(got.codes, i32_vec(&traces["codes"]));
    assert_eq!(got.stopped_by, StopReason::EndOfSpeech);
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(got.samples.len(), want_wave.len());
    let diff = max_abs_diff(&got.samples, &want_wave);
    assert!(diff <= WAVEFORM_TOLERANCE, "eos-first waveform diff {diff}");
}

#[test]
fn greedy_generation_stops_at_end_of_speech_with_reference_tokens() {
    let traces = read_json(&testdata("generate/traces.json"));
    run_generate_scenario(&traces["scenarios"][0]);
}

#[test]
fn greedy_generation_stops_at_max_tokens_with_reference_tokens() {
    let traces = read_json(&testdata("generate/traces.json"));
    run_generate_scenario(&traces["scenarios"][1]);
}

#[test]
fn generate_refuses_an_empty_prompt() {
    let mut model = generate_model();
    let error = model
        .generate_from_prompt(&decode_snac(), &[], &scenario_params(4, 1.3), 0)
        .unwrap_err();
    assert!(error.to_string().contains("empty prompt"), "{error}");
}

#[test]
fn family_config_reads_tokenizer_name_and_sample_rate() {
    let model = generate_model();
    assert_eq!(model.config.tokenizer_name, None);
    assert_eq!(model.config.sample_rate, 24000);
    let defaults = super::ModelConfig::from_json(&serde_json::json!({
        "model_type": "qwen3",
        "hidden_size": 8,
        "num_hidden_layers": 1,
        "intermediate_size": 8,
        "num_attention_heads": 2,
        "num_key_value_heads": 2,
        "head_dim": 4,
        "rms_norm_eps": 1e-5,
        "vocab_size": 8,
        "max_position_embeddings": 64,
        "rope_theta": 1000000.0,
        "tie_word_embeddings": true,
    }))
    .unwrap();
    assert_eq!(defaults.tokenizer_name, None);
    assert_eq!(defaults.sample_rate, super::DEFAULT_SAMPLE_RATE);
}

#[test]
fn sampling_filters_match_the_reference_on_fixed_logits() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().expect("cases") {
        let mut logits = f32_vec(&case["logits"]);
        let context = i32_vec(&case["context"]);
        let bias: Vec<(i32, f32)> = case["logit_bias"]
            .as_array()
            .expect("bias")
            .iter()
            .map(|pair| {
                (
                    pair[0].as_i64().expect("token") as i32,
                    pair[1].as_f64().expect("bias") as f32,
                )
            })
            .collect();
        // Reference order: logit bias first, then the repetition penalty.
        sampling::apply_logit_bias(&mut logits, &bias).unwrap();
        let penalty = case["repetition_penalty"].as_f64().expect("penalty") as f32;
        if penalty != 0.0 {
            sampling::apply_repetition_penalty(
                &mut logits,
                &context,
                penalty,
                case["repetition_context_size"].as_u64().expect("context") as usize,
            )
            .unwrap();
        }
        let diff = max_abs_diff(&logits, &f32_vec(&case["processed_logits"]));
        assert!(
            diff <= SAMPLING_TOLERANCE,
            "case {} processed logits diff {diff}",
            case["name"]
        );

        let logprobs = sampling::log_softmax(&logits);
        let diff = max_abs_diff(&logprobs, &f32_vec(&case["logprobs"]));
        assert!(
            diff <= SAMPLING_TOLERANCE,
            "case {} logprobs diff {diff}",
            case["name"]
        );

        // The greedy path takes the argmax of the processed logits, the
        // same point the reference sampler starts from.
        let want_argmax = case["argmax"].as_u64().expect("argmax") as usize;
        assert_eq!(
            sampling::argmax(&logprobs),
            want_argmax,
            "case {}",
            case["name"]
        );

        let mut filtered = logprobs.clone();
        if let Some(top_p) = case["top_p_logprobs"].as_array() {
            sampling::apply_top_p(&mut filtered, case["top_p"].as_f64().unwrap() as f32);
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_p.clone())));
            assert!(
                diff <= SAMPLING_TOLERANCE,
                "case {} top_p diff {diff}",
                case["name"]
            );
        }
        if let Some(top_k) = case["top_k_logprobs"].as_array() {
            sampling::apply_top_k(
                &mut filtered,
                case["top_k"].as_u64().expect("top_k") as usize,
            )
            .unwrap();
            let diff = max_abs_diff(&filtered, &f32_vec_masked(&Value::Array(top_k.clone())));
            assert!(
                diff <= SAMPLING_TOLERANCE,
                "case {} top_k diff {diff}",
                case["name"]
            );
        }
    }
}

#[test]
fn special_token_constants_match_the_reference() {
    assert_eq!(super::TOKENIZER_LENGTH, 151669);
    assert_eq!(super::START_OF_TEXT, 151643);
    assert_eq!(END_OF_TEXT, 151645);
    assert_eq!(START_OF_SPEECH, 151670);
    assert_eq!(END_OF_SPEECH, 151671);
    assert_eq!(START_OF_HUMAN, 151672);
    assert_eq!(END_OF_HUMAN, 151673);
    assert_eq!(super::START_OF_AI, 151674);
    assert_eq!(super::END_OF_AI, 151675);
    assert_eq!(super::PAD_TOKEN, 151676);
    assert_eq!(super::AUDIO_TOKENS_START, 151679);
}
